import collections, random
random.seed(2)
qs = {"w1": collections.deque(["t1", "t2", "t3"]), "w2": collections.deque([])}
def steal(thief):
    victims = [w for w in qs if w != thief and qs[w]]
    if victims:
        v = random.choice(victims)
        return qs[v].pop()
    return None
print("w2 steals:", steal("w2"), "| w1 left:", list(qs["w1"]))

